    /// <summary>tempfile (subset): the temporary directory and fresh temporary directories/files.</summary>
    internal static class tempfile
    {
        public static string gettempdir() => System.IO.Path.GetTempPath().TrimEnd(System.IO.Path.DirectorySeparatorChar);
        public static string mkdtemp(string suffix = "", string prefix = "tmp", string? dir = null)
        {
            string path = System.IO.Path.Combine(dir ?? gettempdir(), prefix + System.IO.Path.GetRandomFileName().Replace(".", "") + suffix);
            System.IO.Directory.CreateDirectory(path);
            return path;
        }
        internal sealed class TemporaryDirectory
        {
            public readonly string name;
            readonly bool _ignoreCleanupErrors;
            readonly bool _delete;

            public TemporaryDirectory(string? suffix = null, string? prefix = null, string? dir = null,
                bool ignore_cleanup_errors = false, bool delete = true)
            {
                name = System.IO.Path.GetFullPath(mkdtemp(suffix ?? "", prefix ?? "tmp", dir));
                _ignoreCleanupErrors = ignore_cleanup_errors;
                _delete = delete;
            }

            public string __enter__() => name;

            public bool __exit__(object? type, object? exc, object? traceback)
            {
                if (_delete) cleanup();
                return false;
            }

            public void cleanup()
            {
                Remove(_ignoreCleanupErrors);
                GC.SuppressFinalize(this);
            }

            void Remove(bool ignoreErrors)
            {
                if (name == null) return;
                try { System.IO.Directory.Delete(name, recursive: true); }
                catch (System.IO.DirectoryNotFoundException) { }
                catch (System.IO.IOException) when (ignoreErrors) { }
                catch (UnauthorizedAccessException) when (ignoreErrors) { }
            }

            ~TemporaryDirectory()
            {
                if (_delete) Remove(ignoreErrors: true);
            }
        }

        public static (long, string) mkstemp(string suffix = "", string prefix = "tmp", string? dir = null)
        {
            string path = System.IO.Path.Combine(dir ?? gettempdir(), prefix + System.IO.Path.GetRandomFileName().Replace(".", "") + suffix);
            System.IO.File.WriteAllBytes(path, Array.Empty<byte>());
            return (0, path);
        }
    }

    /// <summary>itertools: combinatoric and infinite iterators. Tuples of computed length are PyTuples, fixed shapes ValueTuples.</summary>
    internal static class itertools
    {
        static IEnumerable<string> Chars(string s) => new StrChars(s);

        public static IEnumerable<PyTuple<T>> permutations<T>(IEnumerable<T> iterable, long? r = null)
        {
            var pool = iterable.ToArray();
            int n = pool.Length, k = (int)(r ?? n);
            if (k > n || k < 0) yield break;
            var idx = Enumerable.Range(0, n).ToArray();
            var cycles = Enumerable.Range(n - k + 1, k).Reverse().ToArray();
            yield return new PyTuple<T>(idx.Take(k).Select(i => pool[i]).ToArray());
            while (n > 0)
            {
                bool done = true;
                for (int i = k - 1; i >= 0; i--)
                {
                    cycles[i]--;
                    if (cycles[i] == 0)
                    {
                        int first = idx[i];
                        Array.Copy(idx, i + 1, idx, i, n - i - 1);
                        idx[n - 1] = first;
                        cycles[i] = n - i;
                    }
                    else
                    {
                        int j = n - cycles[i];
                        (idx[i], idx[j]) = (idx[j], idx[i]);
                        yield return new PyTuple<T>(idx.Take(k).Select(x => pool[x]).ToArray());
                        done = false;
                        break;
                    }
                }
                if (done) yield break;
            }
        }
        public static IEnumerable<PyTuple<string>> permutations(string s, long? r = null) => permutations(Chars(s), r);

        public static IEnumerable<PyTuple<T>> combinations<T>(IEnumerable<T> iterable, long r)
        {
            var pool = iterable.ToArray();
            int n = pool.Length, k = (int)r;
            if (k > n || k < 0) yield break;
            var idx = Enumerable.Range(0, k).ToArray();
            yield return new PyTuple<T>(idx.Select(i => pool[i]).ToArray());
            while (true)
            {
                int i = k - 1;
                while (i >= 0 && idx[i] == i + n - k) i--;
                if (i < 0) yield break;
                idx[i]++;
                for (int j = i + 1; j < k; j++) idx[j] = idx[j - 1] + 1;
                yield return new PyTuple<T>(idx.Select(x => pool[x]).ToArray());
            }
        }
        public static IEnumerable<PyTuple<string>> combinations(string s, long r) => combinations(Chars(s), r);

        public static IEnumerable<PyTuple<T>> combinations_with_replacement<T>(IEnumerable<T> iterable, long r)
        {
            var pool = iterable.ToArray();
            int n = pool.Length, k = (int)r;
            if (n == 0 && k > 0) yield break;
            var idx = new int[k];
            yield return new PyTuple<T>(idx.Select(i => pool[i]).ToArray());
            while (true)
            {
                int i = k - 1;
                while (i >= 0 && idx[i] == n - 1) i--;
                if (i < 0) yield break;
                int v = idx[i] + 1;
                for (int j = i; j < k; j++) idx[j] = v;
                yield return new PyTuple<T>(idx.Select(x => pool[x]).ToArray());
            }
        }
        public static IEnumerable<PyTuple<string>> combinations_with_replacement(string s, long r) => combinations_with_replacement(Chars(s), r);

        public static IEnumerable<(A, B)> product<A, B>(IEnumerable<A> a, IEnumerable<B> b)
        {
            var bs = b.ToList();
            foreach (var x in a.ToList()) foreach (var y in bs) yield return (x, y);
        }
        public static IEnumerable<(A, B, C)> product<A, B, C>(IEnumerable<A> a, IEnumerable<B> b, IEnumerable<C> c)
        {
            var bs = b.ToList(); var cs = c.ToList();
            foreach (var x in a.ToList()) foreach (var y in bs) foreach (var z in cs) yield return (x, y, z);
        }
        public static IEnumerable<PyTuple<T>> product<T>(IEnumerable<T> a, long repeat) => product(Enumerable.Repeat(a.ToList(), (int)repeat).ToArray());
        public static IEnumerable<PyTuple<string>> product(string a, long repeat) => product(Chars(a), repeat);
        public static IEnumerable<PyTuple<T>> product<T>(params IEnumerable<T>[] iterables)
        {
            var pools = iterables.Select(p => p.ToArray()).ToArray();
            IEnumerable<T[]> acc = new[] { Array.Empty<T>() };
            foreach (var pool in pools) acc = acc.SelectMany(prefix => pool.Select(x => prefix.Append(x).ToArray())).ToList();
            return acc.Select(t => new PyTuple<T>(t));
        }

        public static PyIterator<long> count(long start = 0, long step = 1) => CountFrom(start, step);
        public static PyIterator<double> count(double start, double step = 1) => CountFrom(start, step);
        public static PyIterator<BigInteger> count(BigInteger start, BigInteger step) => CountFrom(start, step);
        public static PyIterator<BigInteger> count(BigInteger start) => CountFrom(start, BigInteger.One);

        static PyIterator<T> CountFrom<T>(T start, T step) where T : INumber<T>
        {
            static IEnumerable<T> Values(T start, T step)
            {
                for (T value = start; ; value = checked(value + step)) yield return value;
            }
            return new PyIterator<T>(Values(start, step).GetEnumerator());
        }

        public static IEnumerable<T> cycle<T>(IEnumerable<T> iterable)
        {
            var saved = new List<T>();
            foreach (var x in iterable) { saved.Add(x); yield return x; }
            if (saved.Count == 0) yield break;
            while (true) foreach (var x in saved) yield return x;
        }
        public static IEnumerable<string> cycle(string s) => cycle(Chars(s));
        public static PyIterator<object?> repeat(object? @object) => repeat<object?>(@object);
        public static PyIterator<object?> repeat(object? @object, object? times) => repeat<object?>(@object, times);
        public static PyIterator<T> repeat<T>(T @object) => new(RepeatItems(@object, null).GetEnumerator());
        public static PyIterator<T> repeat<T>(T @object, object? times) =>
            new(RepeatItems(@object, checked((long)Builtins.RangeIndex(times))).GetEnumerator());

        static IEnumerable<T> RepeatItems<T>(T value, long? count)
        {
            if (count == null) while (true) yield return value;
            for (long index = 0; index < count; index++) yield return value;
        }

        public static IEnumerable<T> islice<T>(IEnumerable<T> iterable, long? stop) => islice(iterable, 0, stop, 1);
        public static IEnumerable<dynamic> islice(object? iterable, object? stop) =>
            islice(Builtins.__iter_dyn(iterable), IsliceIndex(stop));
        public static IEnumerable<dynamic> islice(object? iterable, object? start, object? stop, object? step = null) =>
            islice(Builtins.__iter_dyn(iterable), IsliceIndex(start), IsliceIndex(stop), IsliceIndex(step));

        static long? IsliceIndex(object? value)
        {
            if (value == null) return null;
            try
            {
                object index = Builtins.__index_value(value);
                return index is BigInteger wide ? (long)wide : (long)index;
            }
            catch (Exception error) when (error is OverflowException or InvalidCastException)
            {
                throw new ArgumentException("Indices for islice() must be None or an integer: 0 <= x <= sys.maxsize.");
            }
        }

        public static IEnumerable<T> islice<T>(IEnumerable<T> iterable, long? start, long? stop, long? step = 1)
        {
            long s = start ?? 0, st = step ?? 1;
            if (s < 0 || st <= 0 || stop < 0) throw new ArgumentException("Indices for islice() must be None or an integer: 0 <= x <= sys.maxsize.");
            var iterator = iterable.GetEnumerator();
            return new PyIterator<T>(Read().GetEnumerator());

            IEnumerable<T> Read()
            {
                long next = s;
                long limit = stop == null ? long.MaxValue : Math.Max(s, stop.Value);
                for (long i = 0; i < limit && iterator.MoveNext(); i++)
                {
                    if (i != next || i >= stop) continue;
                    yield return iterator.Current;
                    next = next > long.MaxValue - st ? long.MaxValue : next + st;
                }
            }
        }
        public static PyIterator<T> chain<T>(params IEnumerable<T>[] iterables) => chain_from_iterable(iterables);
        public static PyIterator<dynamic> chain(params object?[] iterables) =>
            chain_from_iterable(iterables.Select(iterator => Builtins.__iter_dyn(iterator)));

        public static PyIterator<dynamic> chain_from_iterable([PyPositionalOnly] object? iterable) =>
            chain_from_iterable(Builtins.__iter_dyn(iterable).Select(item => Builtins.__iter_dyn((object?)item)));

        public static PyIterator<object?> starmap([PyPositionalOnly] object? function, [PyPositionalOnly] object? iterable)
        {
            var source = Builtins.__iter_dyn(iterable);
            return new PyIterator<object?>(Apply().GetEnumerator());

            IEnumerable<object?> Apply()
            {
                foreach (object? args in source)
                    yield return Builtins.__invoke(function, Builtins.__iter_dyn(args).ToArray());
            }
        }

        public static PyIterator<T> chain_from_iterable<T>(IEnumerable<IEnumerable<T>> iterables)
        {
            return new PyIterator<T>(Items().GetEnumerator());

            IEnumerable<T> Items()
            {
                foreach (var iterator in iterables)
                    foreach (var item in iterator)
                        yield return item;
            }
        }
        public static IEnumerable<long> accumulate(IEnumerable<long> xs) { long s = 0; bool any = false; foreach (var x in xs) { s = any ? checked(s + x) : x; any = true; yield return s; } }
        public static IEnumerable<double> accumulate(IEnumerable<double> xs) { double s = 0; bool any = false; foreach (var x in xs) { s = any ? s + x : x; any = true; yield return s; } }
        public static IEnumerable<T> accumulate<T>(IEnumerable<T> xs, Func<T, T, T> func)
        {
            bool any = false; T acc = default!;
            foreach (var x in xs) { acc = any ? func(acc, x) : x; any = true; yield return acc; }
        }
        public static IEnumerable<T> takewhile<T>(Func<T, bool> predicate, IEnumerable<T> iterable) { foreach (var x in iterable) { if (!predicate(x)) yield break; yield return x; } }
        public static IEnumerable<T> takewhile<T>(object predicate, IEnumerable<T> iterable) =>
            takewhile(value => Builtins.truthy((object?)Builtins.__invoke(predicate, [value])), iterable);
        public static IEnumerable<dynamic> takewhile(object predicate, object iterable) =>
            takewhile(predicate, Builtins.__iter_dyn(iterable));
        public static IEnumerable<T> dropwhile<T>(Func<T, bool> predicate, IEnumerable<T> iterable)
        {
            bool dropping = true;
            foreach (var x in iterable) { if (dropping && predicate(x)) continue; dropping = false; yield return x; }
        }
        public static IEnumerable<T> filterfalse<T>(Func<T, bool>? predicate, IEnumerable<T> iterable) =>
            predicate == null ? filterfalse((object?)null, iterable) : iterable.Where(x => !predicate(x));
        public static IEnumerable<T> filterfalse<T>(object? predicate, IEnumerable<T> iterable) =>
            iterable.Where(item => !Builtins.truthy(predicate == null ? item : Builtins.__invoke(predicate, [item])));
        public static IEnumerable<dynamic> filterfalse(object? predicate, object? iterable) =>
            filterfalse(predicate, Builtins.__iter_dyn(iterable));
        public static IEnumerable<T> compress<T>(IEnumerable<T> data, IEnumerable<bool> selectors) => data.Zip(selectors).Where(p => p.Second).Select(p => p.First);
        public static IEnumerable<T> compress<T>(IEnumerable<T> data, IEnumerable<long> selectors) => data.Zip(selectors).Where(p => p.Second != 0).Select(p => p.First);
        public static IEnumerable<(T, T)> pairwise<T>(IEnumerable<T> iterable)
        {
            bool first = true; T prev = default!;
            foreach (var x in iterable) { if (!first) yield return (prev, x); prev = x; first = false; }
        }
        public static IEnumerable<(string, string)> pairwise(string s) => pairwise(Chars(s));
        public static IEnumerable<PyTuple<T>> batched<T>(IEnumerable<T> iterable, long n) => iterable.Chunk((int)n).Select(c => new PyTuple<T>(c));
        public static IEnumerable<(K, List<T>)> groupby<T, K>(IEnumerable<T> iterable, Func<T, K> key)
        {
            List<T>? group = null; K current = default!;
            foreach (var x in iterable)
            {
                var k = key(x);
                if (group != null && Builtins.eq(k, current)) { group.Add(x); continue; }
                if (group != null) yield return (current, group);
                current = k; group = new List<T> { x };
            }
            if (group != null) yield return (current, group);
        }
        public static IEnumerable<(T, List<T>)> groupby<T>(IEnumerable<T> iterable) => groupby(iterable, x => x);
        public static IEnumerable<(string, List<string>)> groupby(string s) => groupby(Chars(s), x => x);
        public static PyTuple<IEnumerable<T>> tee<T>(IEnumerable<T> iterable, long n = 2) { var items = iterable.ToList(); return new PyTuple<IEnumerable<T>>(Enumerable.Range(0, (int)n).Select(_ => (IEnumerable<T>)items)); }
    }

    /// <summary>collections: Counter, defaultdict, deque, OrderedDict (the classes live in Typhon.Runtime).</summary>
    internal static partial class collections
    {
        internal static readonly Dictionary<string, Type> RuntimeClasses = new(StringComparer.Ordinal)
        {
            ["Counter"] = typeof(Typhon.Runtime.Counter<object>),
            ["defaultdict"] = typeof(Typhon.Runtime.defaultdict<object, object>),
            ["deque"] = typeof(Typhon.Runtime.deque<object>),
            ["OrderedDict"] = typeof(PyOrderedDict<object, object>),
        };

        internal static Type? CanonicalClass(Type type)
        {
            if (!type.IsGenericType) return null;
            var definition = type.GetGenericTypeDefinition();
            if (definition == typeof(Typhon.Runtime.Counter<>)) return typeof(Typhon.Runtime.Counter<object>);
            if (definition == typeof(Typhon.Runtime.defaultdict<,>)) return typeof(Typhon.Runtime.defaultdict<object, object>);
            if (definition == typeof(Typhon.Runtime.deque<>)) return typeof(Typhon.Runtime.deque<object>);
            if (definition == typeof(PyOrderedDict<,>)) return typeof(PyOrderedDict<object, object>);
            return null;
        }

        public static Typhon.Runtime.Counter<T> Counter<T>(IEnumerable<T> iterable) where T : notnull => new Typhon.Runtime.Counter<T>(iterable);
        public static Typhon.Runtime.Counter<string> Counter(string s) => new Typhon.Runtime.Counter<string>(new StrChars(s));
        public static Typhon.Runtime.Counter<T> Counter<T>(IDictionary<T, long> counts) where T : notnull { var c = new Typhon.Runtime.Counter<T>(); c.update(counts); return c; }
        public static Typhon.Runtime.deque<dynamic> deque(long? maxlen = null) => new Typhon.Runtime.deque<dynamic>(maxlen);
        public static Typhon.Runtime.deque<T> deque<T>(IEnumerable<T> iterable, long? maxlen = null) => new Typhon.Runtime.deque<T>(iterable, maxlen);
        public static Typhon.Runtime.deque<string> deque(string s, long? maxlen = null) => new Typhon.Runtime.deque<string>(new StrChars(s), maxlen);
        public static PyOrderedDict<K, V> OrderedDict<K, V>(IDictionary<K, V> d) where K : notnull { var o = new PyOrderedDict<K, V>(); foreach (var kv in d) o[kv.Key] = kv.Value; return o; }
        public static PyOrderedDict<K, V> OrderedDict<K, V>(IEnumerable<(K, V)> pairs) where K : notnull { var o = new PyOrderedDict<K, V>(); foreach (var (k, v) in pairs) o[k] = v; return o; }
    }

    /// <summary>functools function helpers, including the runtime cache wrappers.</summary>
    internal static partial class functools
    {
        /// <summary>@functools.wraps(f) on a decorator's wrapper: the wrapper takes f's name and docstring, and keeps f as __wrapped__.</summary>
        public static dynamic wraps(object? wrapped) => new PyClosure("wraps", (a, kw) => update_wrapper(a[0], wrapped));
        public static dynamic? update_wrapper(object? wrapper, object? wrapped)
        {
            if (wrapper is PyFunction w)
            {
                if (wrapped is PyFunction src) { w.__name__ = src.__name__; w.__doc__ = src.__doc__; w.__module__ = src.__module__; }
                w.__wrapped__ = wrapped;
            }
            return wrapper;
        }
        /// <summary>functools.partial(f, *args, **keywords) (a call with keywords goes to __partial_kw).</summary>
        public static dynamic partial(object? func, params object?[] args) => new PyPartial(func, args, null);
        public static dynamic __partial_kw(object? func, object?[] args, IDictionary<string, object?> keywords) => new PyPartial(func, args, keywords);
        public static T reduce<T>(Func<T, T, T> function, IEnumerable<T> iterable)
        {
            using var e = iterable.GetEnumerator();
            if (!e.MoveNext()) throw new InvalidCastException("reduce() of empty iterable with no initial value");
            var acc = e.Current;
            while (e.MoveNext()) acc = function(acc, e.Current);
            return acc;
        }
        public static A reduce<T, A>(Func<A, T, A> function, IEnumerable<T> iterable, A initial)
        {
            var acc = initial;
            foreach (var x in iterable) acc = function(acc, x);
            return acc;
        }
        public static dynamic? __reduce(object function, object iterable) =>
            reduce<object?>((accumulator, item) => (object?)Builtins.__invoke(function, [accumulator, item]), Builtins.__iter_dyn(iterable));

        public static dynamic? __reduce(object function, object iterable, object? initial) =>
            reduce<object?, object?>((accumulator, item) => (object?)Builtins.__invoke(function, [accumulator, item]), Builtins.__iter_dyn(iterable), initial);

        public static Func<T, CmpKey<T>> cmp_to_key<T>(Func<T, T, long> mycmp) => x => new CmpKey<T>(x, mycmp);
        public static PyClosure __cmp_to_key(object mycmp)
        {
            long Compare(object? left, object? right) => Builtins.@int((object)Builtins.__invoke(mycmp, [left, right]));
            return new PyClosure("cmp_to_key", (args, keywords) =>
            {
                if (args.Length != 1 || keywords?.Count > 0)
                    throw PyClosure.ArgCountError("cmp_to_key", 1, 1, args.Length);
                return new CmpKey<object?>(args[0], Compare);
            });
        }
    }

    /// <summary>operator: the operators as functions (for reduce, map, sorted keys).</summary>
    internal static class @operator
    {
        internal sealed class attrgetter : System.Dynamic.DynamicObject, IPyRepr, IPyKeywordCallable
        {
            readonly string[] _names;
            readonly string[][] _paths;

            public attrgetter() => throw new InvalidCastException("attrgetter expected 1 argument, got 0");

            public attrgetter([PyPositionalOnly] object? name, params object?[] more)
            {
                _names = new[] { name }.Concat(more ?? [null]).Select(attribute => attribute as string ??
                    throw new InvalidCastException("attribute name must be a string")).ToArray();
                _paths = _names.Select(attribute => attribute.Split('.')).ToArray();
            }

            static object? Read(object? target, string[] path)
            {
                foreach (string part in path) target = Builtins.getattr(target, part);
                return target;
            }

            public object? __call_kw__(object?[] args, IDictionary<string, object?>? kwargs)
            {
                if (args.Length != 1 || kwargs?.Count > 0)
                    throw PyClosure.ArgCountError("attrgetter", 1, 1, args.Length);
                return _paths.Length == 1 ? Read(args[0], _paths[0]) :
                    new PyTuple<object?>(_paths.Select(path => Read(args[0], path)));
            }

            public override bool TryInvoke(System.Dynamic.InvokeBinder binder, object?[]? args, out object? result)
            {
                if (binder.CallInfo.ArgumentNames.Count != 0)
                    throw new InvalidCastException("attrgetter() takes no keyword arguments");
                result = __call_kw__(args ?? [], null);
                return true;
            }

            public (Type, PyTuple<string>) __reduce__() => (typeof(attrgetter), new PyTuple<string>(_names));
            public string __repr__() => "operator.attrgetter(" + string.Join(", ", _names.Select(name => Builtins.repr(name))) + ")";
            public override string ToString() => __repr__();
        }

        public static dynamic index(object? value) => Builtins.__index_value(value);

        public static long add(long a, long b) => checked(a + b);
        public static double add(double a, double b) => a + b;
        public static string add(string a, string b) => a + b;
        public static long sub(long a, long b) => checked(a - b);
        public static double sub(double a, double b) => a - b;
        public static long mul(long a, long b) => checked(a * b);
        public static double mul(double a, double b) => a * b;
        public static double truediv(double a, double b) => Builtins.truediv(a, b);
        public static long floordiv(long a, long b) => Builtins.floordiv(a, b);
        public static long mod(long a, long b) => Builtins.mod(a, b);
        public static dynamic lt(object? a, object? b) => Builtins.lt(a, b);
        public static dynamic le(object? a, object? b) => Builtins.le(a, b);
        public static dynamic gt(object? a, object? b) => Builtins.gt(a, b);
        public static dynamic ge(object? a, object? b) => Builtins.ge(a, b);
        public static long neg(long a) => checked(-a);
        public static double neg(double a) => -a;
        public static long and_(long a, long b) => a & b;
        public static long or_(long a, long b) => a | b;
        public static dynamic or_(object? a, object? b) => Builtins.or_((dynamic)a!, (dynamic)b!);
        public static readonly Func<object?, object?, dynamic?> getitem = Builtins.__getitem;
        public static long xor(long a, long b) => a ^ b;
        public static Func<IList<T>, T> itemgetter<T>(long i) => xs => xs[(int)i];

        public static dynamic itemgetter([PyPositionalOnly] object? item, params object?[] more) =>
            new PyClosure("itemgetter", (args, keywords) =>
            {
                if (args.Length != 1 || keywords?.Count > 0)
                    throw PyClosure.ArgCountError("itemgetter", 1, 1, args.Length);
                if (more.Length == 0) return Builtins.__getitem(args[0], item);
                var result = new object?[more.Length + 1];
                result[0] = Builtins.__getitem(args[0], item);
                for (int i = 0; i < more.Length; i++)
                    result[i + 1] = Builtins.__getitem(args[0], more[i]);
                return new PyTuple<object?>(result);
            });
    }

